    { tag: 'rect', attrs: { x: 66, y: 42, width: 18, height: 12, rx: 4 } }, // neck
    { tag: 'ellipse', attrs: { cx: 66, cy: 308, rx: 9, ry: 6 } },       // foot
    { tag: 'ellipse', attrs: { cx: 84, cy: 308, rx: 9, ry: 6 } }        // foot
