    var front = view !== 'back' ? bodyMapFigure(BODYMAP_FRONT_ALL, BODYMAP_FRONT_PRIMARY, data, opts) : '';
    var back = view !== 'front' ? bodyMapFigure(BODYMAP_BACK_ALL, BODYMAP_BACK_PRIMARY, data, opts) : '';
